def targets_from_history(apps, schema_editor):
    """Para no empezar con un 3 inventado: cada ejercicio de la rutina toma como objetivo
    el número de series que hiciste la última vez que entrenaste ese día."""
    RoutineExercise = apps.get_model('workouts', 'RoutineExercise')
    WorkoutSession = apps.get_model('workouts', 'WorkoutSession')
    WorkoutSet = apps.get_model('workouts', 'WorkoutSet')
    for item in RoutineExercise.objects.exclude(routine_day=None).exclude(exercise=None):
        sessions = WorkoutSession.objects.filter(routine_day_id=item.routine_day_id, end_time__isnull=False).order_by('-start_time')
        for session in sessions[:5]:
            count = WorkoutSet.objects.filter(workout_session=session, exercise_snapshot=item.exercise_id).count()
            if count:
                item.target_sets = min(count, 10)
                item.save(update_fields=['target_sets'])
                break


